values
  (null, null, 'ak-ngc', 'salt', 'note', 'North Gulf Coast saltwaters: within 200 miles of shore from the longitude of Gore Point to the longitude of Cape Fairfield. Fishing is open year-round for all species unless otherwise noted. Snagging is legal year-round in all North Gulf Coast saltwaters. Gaffs may not be used to puncture any fish intended or required to be released. Stay legal — before you cast, check emergency orders at www.adfg.alaska.gov/sf/EONR. ATTENTION SALT WATER ANGLERS: Anglers must carry a deepwater release device onboard their vessel when sport fishing in salt water and will be required to use the device to release rockfish that are not harvested at depth of capture or 100 feet.', 'https://www.adfg.alaska.gov/static/regulations/fishregulations/PDFs/southcentral/2026sc_sfregs_north_gulf_coast.pdf', 'ADF&G — 2026 Southcentral Alaska Sport Fishing Regulations Summary Book (North Gulf Coast, Salt Water general & special regulations)', null, '2026-09-02', 2,
   null, null, null, null, null, null, null, null, null, true, 30),
  ('pacific_halibut', null, 'ak-ngc', 'salt', 'season', 'Pacific halibut: Feb. 1-Dec. 31. Unguided anglers: 2 per day, 4 in possession. Consult federal regulations for bag, possession and size limits and other regulations for guided (charter) anglers.', 'https://www.adfg.alaska.gov/static/regulations/fishregulations/PDFs/southcentral/2026sc_sfregs_north_gulf_coast.pdf', 'ADF&G — 2026 Southcentral Alaska Sport Fishing Regulations Summary Book (North Gulf Coast, Salt Water general & special regulations)', null, '2026-09-02', 2,
   '2026-02-01', '2026-12-31', 2, 4, null, null, null, null, null, true, 14),
