   null, null, 1, 1, null, null, null, null, null, true, 14),
  (null, 'akse-4salmon', 'ak-res-bay', 'salt', 'bag_limit', 'Chum, coho, pink, & sockeye salmon (combo) — Saltwaters: Resurrection Bay: Open year-round: 6 per day, 6 in possession, no size limit. All 6 may be coho salmon. Pink salmon taken in the sport fishery may be used as bait, but are part of your bag limit. Pink salmon used as bait must not be alive.', 'https://www.adfg.alaska.gov/static/regulations/fishregulations/PDFs/southcentral/2026sc_sfregs_north_gulf_coast.pdf', 'ADF&G — 2026 Southcentral Alaska Sport Fishing Regulations Summary Book (North Gulf Coast, Salt Water general & special regulations)', null, '2026-09-02', 2,
   null, null, 6, 6, null, null, null, null, null, true, 14),
  (null, 'akse-4salmon', 'ak-ngc', 'salt', 'bag_limit', 'Chum, coho, pink, & sockeye salmon (combo) — Saltwaters: Outside of Resurrection Bay: Open year-round: 6 per day, 6 in possession, no size limit. Only 3 per day, 3 in possession may be coho salmon. It is illegal to fish for species in these waters with more than 3 coho salmon in your possession.', 'https://www.adfg.alaska.gov/static/regulations/fishregulations/PDFs/southcentral/2026sc_sfregs_north_gulf_coast.pdf', 'ADF&G — 2026 Southcentral Alaska Sport Fishing Regulations Summary Book (North Gulf Coast, Salt Water general & special regulations)', null, '2026-09-02', 2,
   null, null, 6, 6, null, null, null, null, 'Only 3 of the 6 may be coho.', true, 14),
  ('steelhead', null, 'ak-ngc', 'salt', 'prohibited', 'Rainbow/steelhead trout (combo): Saltwaters: Closed year-round to all rainbow/steelhead trout fishing. All rainbow/steelhead trout caught may not be removed from the water and must be released immediately.', 'https://www.adfg.alaska.gov/static/regulations/fishregulations/PDFs/southcentral/2026sc_sfregs_north_gulf_coast.pdf', 'ADF&G — 2026 Southcentral Alaska Sport Fishing Regulations Summary Book (North Gulf Coast, Salt Water general & special regulations)', null, '2026-09-02', 2,
   null, null, 0, 0, null, null, null, null, null, true, 60),
  ('dolly_varden', null, 'ak-ngc', 'salt', 'bag_limit', 'Arctic char/Dolly Varden (combo): Saltwaters: Entire North Gulf Coast: Open year-round: 5 per day, 5 in possession, no size limit.', 'https://www.adfg.alaska.gov/static/regulations/fishregulations/PDFs/southcentral/2026sc_sfregs_north_gulf_coast.pdf', 'ADF&G — 2026 Southcentral Alaska Sport Fishing Regulations Summary Book (North Gulf Coast, Salt Water general & special regulations)', null, '2026-09-02', 2,
   null, null, 5, 5, null, null, null, null, null, true, 30),
  ('lingcod', null, 'ak-res-bay', 'salt', 'prohibited', 'Lingcod — Saltwaters: Resurrection Bay (North of line between Cape Resurrection to Aialik Cape): Closed year-round to all lingcod fishing. Lingcod caught incidentally must be released immediately. You cannot legally fish for any species of fish inside Resurrection Bay if you possess a lingcod taken elsewhere.', 'https://www.adfg.alaska.gov/static/regulations/fishregulations/PDFs/southcentral/2026sc_sfregs_north_gulf_coast.pdf', 'ADF&G — 2026 Southcentral Alaska Sport Fishing Regulations Summary Book (North Gulf Coast, Salt Water general & special regulations)', null, '2026-09-02', 2,
   null, null, 0, 0, null, null, null, null, null, true, 30),
  ('lingcod', null, 'ak-ngc', 'salt', 'bag_limit', 'Lingcod — Saltwaters: Outside of Resurrection Bay: July 1-Dec. 31: 1 per day, 2 in possession, must be at least 35 inches long with head attached or 28 inches from tip of tail to front of dorsal fin with head removed.', 'https://www.adfg.alaska.gov/static/regulations/fishregulations/PDFs/southcentral/2026sc_sfregs_north_gulf_coast.pdf', 'ADF&G — 2026 Southcentral Alaska Sport Fishing Regulations Summary Book (North Gulf Coast, Salt Water general & special regulations)', null, '2026-09-02', 2,
   '2026-07-01', '2026-12-31', 1, 2, 35, null, 'total_length', null, null, true, 14),
  ('lingcod', null, 'ak-ngc', 'salt', 'season', 'Lingcod — Saltwaters: Outside of Resurrection Bay: July 1-Dec. 31 (the remaining January 1-June 30 period is closed to lingcod retention).', 'https://www.adfg.alaska.gov/static/regulations/fishregulations/PDFs/southcentral/2026sc_sfregs_north_gulf_coast.pdf', 'ADF&G — 2026 Southcentral Alaska Sport Fishing Regulations Summary Book (North Gulf Coast, Salt Water general & special regulations)', null, '2026-09-02', 2,
   '2026-01-01', '2026-06-30', 0, null, null, null, null, null, null, true, 14),
  ('rockfish', null, 'ak-ngc', 'salt', 'bag_limit', 'Rockfish: Open year-round. In 2026, by emergency order the following apply: Pelagic: 2 per day, 4 in possession. Nonpelagic: 1 per day, 2 in possession. April 1-June 30: No retention of yelloweye rockfish.', 'https://www.adfg.alaska.gov/static/regulations/fishregulations/PDFs/southcentral/2026sc_sfregs_north_gulf_coast.pdf', 'ADF&G — 2026 Southcentral Alaska Sport Fishing Regulations Summary Book (North Gulf Coast, Salt Water general & special regulations)', null, '2026-09-02', 2,
   null, null, 2, 4, null, null, null, null, '2026 EO grid: pelagic 2/day; nonpelagic 1/day; yelloweye closed Apr 1-Jun 30.', true, 14),
  ('yelloweye_rockfish', null, 'ak-ngc', 'salt', 'season', 'Rockfish 2026 emergency order: April 1-June 30: No retention of yelloweye rockfish.', 'https://www.adfg.alaska.gov/static/regulations/fishregulations/PDFs/southcentral/2026sc_sfregs_north_gulf_coast.pdf', 'ADF&G — 2026 Southcentral Alaska Sport Fishing Regulations Summary Book (North Gulf Coast, Salt Water general & special regulations)', null, '2026-09-02', 2,
   '2026-04-01', '2026-06-30', 0, null, null, null, null, null, null, true, 14),
  (null, null, 'ak-ngc', 'salt', 'note', 'Sharks except spiny dogfish: Open year-round: 1 per day, 1 in possession, no size limit. There is an annual limit of 2 sharks. Harvest record required. Spiny dogfish: 5 per day, 5 in possession, no size limit. Other finfish: no limit.', 'https://www.adfg.alaska.gov/static/regulations/fishregulations/PDFs/southcentral/2026sc_sfregs_north_gulf_coast.pdf', 'ADF&G — 2026 Southcentral Alaska Sport Fishing Regulations Summary Book (North Gulf Coast, Salt Water general & special regulations)', null, '2026-09-02', 2,
   null, null, null, null, null, null, null, null, null, true, 60),
  (null, null, 'ak-kodiak', 'salt', 'note', 'Inclusive waters: All salt waters circumjacent to Kodiak Island, the Aleutian Islands, and the Alaska Peninsula (coastline west of the longitude of Cape Douglas and Bering Sea coastline south of the latitude of Cape Menshikof). Fishing is open year-round for all species unless otherwise noted. Stay legal — before you cast, check emergency orders at www.adfg.alaska.gov/sf/EONR. Questions? Please contact the Kodiak area office at (907) 486-1880.', 'https://www.adfg.alaska.gov/static/regulations/fishregulations/PDFs/Southwest/2026sw_sfregs_kodiak_akpen_aleutian_salt.pdf', 'ADF&G — 2026 Southwest Alaska Sport Fishing Regulations Summary Book (Kodiak Island, Alaska Peninsula & Aleutian Islands salt water)', null, '2026-09-02', 2,
   null, null, null, null, null, null, null, null, null, true, 30),
  ('chinook_salmon', null, 'ak-kodiak', 'salt', 'season', 'King salmon — In 2026, in the salt waters of the southern Alaska Peninsula west to Scotch Cap on Unimak Island and waters circumjacent to Kodiak Island by emergency order: April 1-September 15: 1 per day, 1 in possession, any size. In 2026, in the westside salt waters of Kodiak Island by emergency order: May 1-June 30: Closed to king salmon fishing. (Otherwise) 2 per day, 2 in possession, no size or annual limit.', 'https://www.adfg.alaska.gov/static/regulations/fishregulations/PDFs/Southwest/2026sw_sfregs_kodiak_akpen_aleutian_salt.pdf', 'ADF&G — 2026 Southwest Alaska Sport Fishing Regulations Summary Book (Kodiak Island, Alaska Peninsula & Aleutian Islands salt water)', null, '2026-09-02', 2,
   '2026-04-01', '2026-09-15', 1, 1, null, null, null, null, 'Westside Kodiak: closed May 1-Jun 30. Outside Apr 1-Sep 15: 2/day.', true, 7),
  ('chinook_salmon', null, 'ak-kodiak-north-belt', 'salt', 'season', 'In 2026, in the westside salt waters of Kodiak Island by emergency order: May 1-June 30: Closed to king salmon fishing.', 'https://www.adfg.alaska.gov/static/regulations/fishregulations/PDFs/Southwest/2026sw_sfregs_kodiak_akpen_aleutian_salt.pdf', 'ADF&G — 2026 Southwest Alaska Sport Fishing Regulations Summary Book (Kodiak Island, Alaska Peninsula & Aleutian Islands salt water)', null, '2026-09-02', 2,
   '2026-05-01', '2026-06-30', 0, null, null, null, null, null, null, true, 7),
  (null, 'akse-4salmon', 'ak-kodiak', 'salt', 'bag_limit', 'Chum, coho, pink, & sockeye salmon (combo): Kodiak and Alaska Peninsula/Aleutian Islands Remote Zones: 5 per day, 10 in possession. Kodiak Road Zone: 5 per day, 5 in possession, only 2 of which may be sockeye salmon. January 1-September 15: Only 2 of which may be coho salmon. September 16-December 31: Only 1 of which may be a coho salmon. Unalaska Bay: 5 per day, 5 in possession, only 2 of which may be coho salmon and 2 of which may be sockeye salmon.', 'https://www.adfg.alaska.gov/static/regulations/fishregulations/PDFs/Southwest/2026sw_sfregs_kodiak_akpen_aleutian_salt.pdf', 'ADF&G — 2026 Southwest Alaska Sport Fishing Regulations Summary Book (Kodiak Island, Alaska Peninsula & Aleutian Islands salt water)', null, '2026-09-02', 2,
   null, null, 5, 10, null, null, null, null, 'Road Zone: 5/day 5 poss, ≤2 sockeye; coho ≤2 Jan 1–Sep 15, ≤1 Sep 16–Dec 31.', true, 14),
  ('steelhead', null, 'ak-kodiak', 'salt', 'bag_limit', 'Rainbow/steelhead trout: 2 per day, 2 in possession, only 1 of which may be 20 inches or longer (except Kodiak Road Zone, see page 23). There is an annual limit of 2 fish 20 inches or longer. Harvest record required.', 'https://www.adfg.alaska.gov/static/regulations/fishregulations/PDFs/Southwest/2026sw_sfregs_kodiak_akpen_aleutian_salt.pdf', 'ADF&G — 2026 Southwest Alaska Sport Fishing Regulations Summary Book (Kodiak Island, Alaska Peninsula & Aleutian Islands salt water)', null, '2026-09-02', 2,
