  ('dolly_varden', null, 'ak-kodiak', 'salt', 'bag_limit', 'Dolly Varden: 10 per day, 10 in possession, no size limit.', 'https://www.adfg.alaska.gov/static/regulations/fishregulations/PDFs/Southwest/2026sw_sfregs_kodiak_akpen_aleutian_salt.pdf', 'ADF&G — 2026 Southwest Alaska Sport Fishing Regulations Summary Book (Kodiak Island, Alaska Peninsula & Aleutian Islands salt water)', null, '2026-09-02', 2,
   null, null, 10, 10, null, null, null, null, null, true, 30),
  ('lingcod', null, 'ak-kodiak', 'salt', 'season', 'Lingcod: July 1-December 31: Open to lingcod fishing. Afognak and Shuyak Islands - north of the latitude of Tonki Cape (north of 58°21.181''N. lat.) and north of the latitude of Black Cape (north of 58°24.583''N. lat.), inclusive of all waters between these points by emergency order: 1 per day, 1 in possession, 35 inches or longer. Remainder of Alaska Peninsula, Aleutian Islands, and Kodiak Island: 2 per day, 4 in possession, no size limit.', 'https://www.adfg.alaska.gov/static/regulations/fishregulations/PDFs/Southwest/2026sw_sfregs_kodiak_akpen_aleutian_salt.pdf', 'ADF&G — 2026 Southwest Alaska Sport Fishing Regulations Summary Book (Kodiak Island, Alaska Peninsula & Aleutian Islands salt water)', null, '2026-09-02', 2,
