  ('lingcod', null, 'ak-kodiak', 'salt', 'season', 'Lingcod: July 1-December 31: Open to lingcod fishing. (January 1-June 30 closed.)', 'https://www.adfg.alaska.gov/static/regulations/fishregulations/PDFs/Southwest/2026sw_sfregs_kodiak_akpen_aleutian_salt.pdf', 'ADF&G — 2026 Southwest Alaska Sport Fishing Regulations Summary Book (Kodiak Island, Alaska Peninsula & Aleutian Islands salt water)', null, '2026-09-02', 2,
   '2026-01-01', '2026-06-30', 0, null, null, null, null, null, null, true, 14),
