   null, null, 3, 3, null, null, null, null, '≤1 of a single species.', true, 7),
  ('rockfish', null, 'ak-kodiak', 'salt', 'bag_limit', 'Rockfish — Remainder of Kodiak Island: 5 per day, 10 in possession, only 2 per day, 4 in possession may be nonpelagic (see page 34), only 1 per day, 2 in possession may be a yelloweye rockfish. Alaska Peninsula & Aleutian Islands: 10 per day, 20 in possession.', 'https://www.adfg.alaska.gov/static/regulations/fishregulations/PDFs/Southwest/2026sw_sfregs_kodiak_akpen_aleutian_salt.pdf', 'ADF&G — 2026 Southwest Alaska Sport Fishing Regulations Summary Book (Kodiak Island, Alaska Peninsula & Aleutian Islands salt water)', null, '2026-09-02', 2,
