  (null, null, 'ak-kodiak', 'salt', 'note', 'Sharks (except spiny dogfish): 1 per day, 1 in possession, no size limit. Annual limit of 2 sharks. Harvest record required. Spiny dogfish: 5 per day, 5 in possession, no size limit. Other finfish: no limit.', 'https://www.adfg.alaska.gov/static/regulations/fishregulations/PDFs/Southwest/2026sw_sfregs_kodiak_akpen_aleutian_salt.pdf', 'ADF&G — 2026 Southwest Alaska Sport Fishing Regulations Summary Book (Kodiak Island, Alaska Peninsula & Aleutian Islands salt water)', null, '2026-09-02', 2,
   null, null, null, null, null, null, null, null, null, true, 60),
  ('dungeness_crab', null, 'ak-kodiak', 'salt', 'note', 'King crab — Alaska Peninsula and Aleutian Islands (golden king crab): Males only: 6 per day, 6 in possession, 6½ inches or more (straight line distance across carapace, not including spines). Red or blue king crab may not be retained or possessed. Kodiak Area: Closed to all king crab species. Tanner crab: Males only: 6 per day, 6 in possession, 5½ inches or more (straight line distance across carapace, including spines). In a commercial Tanner crab section of the Kodiak District that will be open to a commercial Tanner crab fishery, the taking of Tanner crab is prohibited in waters 25 fathoms or more in depth during the 14 days immediately before the scheduled opening of a commercial Tanner crab fishing season in that section. Dungeness crab: Males only: 12 per day, 12 in possession, 6½ inches or more.', 'https://www.adfg.alaska.gov/static/regulations/fishregulations/PDFs/Southwest/2026sw_sfregs_kodiak_akpen_aleutian_salt.pdf', 'ADF&G — 2026 Southwest Alaska Sport Fishing Regulations Summary Book (Kodiak Island, Alaska Peninsula & Aleutian Islands salt water)', null, '2026-09-02', 2,
   null, null, 12, 12, 6.5, null, null, null, 'Males only. Golden king (AkPen/Aleutians): 6@6½in; Tanner: 6@5½in w/ 14-day pre-opener ≥25fm rule; Kodiak closed to king crab.', true, 60);

insert into public.reg_pack (id, version, published_at, notes) values
  ('alaska-2026-09-02', 2, '2026-09-02T18:00:00Z', 'Alaska — Southeast (ADF&G 2026 Region 1 summary book): saltwater year-round except halibut/lingcod/DSR/crab/shrimp. Lingcod May 16–Nov 30 w/ nonresident 30–35 in-or-55 in+ slot and 2/yr; DSR nonresidents Jul 1–Aug 25 only, annual 1; halibut closed January, unguided 2/day; pelagic 3 / slope 1 / DSR 1 rockfish regimes; deepwater release device mandatory; EEZ switches everyone to nonresident limits. Emergency orders control king salmon annually. v2 adds North Gulf Coast (Resurrection Bay closures, NGC king/salmon/lingcod/EO rockfish table) and Kodiak/Southwest (2026 EO king salmon + rockfish grid, lingcod, crab tables, halibut Feb-Dec) verbatim.')
on conflict (id) do update set version = excluded.version, notes = excluded.notes;
